import manifest from "./avatar-manifest.json";

/**
 * Built-in avatars: original illustrations generated by scripts/generate-avatars.mjs into
 * public/avatars/v2 (WebP). First-generation avatars are kept as "legacy" entries: still valid
 * for profiles that use them, but no longer offered in the picker.
 */
export interface BuiltinAvatar {
  id: string;
  collection: string;
  label: string;
  src: string;
}

export const AVATAR_COLLECTIONS: Array<{ id: string; label: string }> = manifest.collections;
export const BUILTIN_AVATARS: BuiltinAvatar[] = manifest.avatars;

/** Defaults for new accounts and new profiles. */
export const DEFAULT_AVATAR = "builtin:v2-space-astronaut";
export const DEFAULT_KIDS_AVATAR = "builtin:v2-monsters-cyclops";

const BY_ID = new Map<string, { label: string; src: string }>([
  ...manifest.legacy.map((a) => [a.id, { label: a.id, src: a.src }] as const),
  ...BUILTIN_AVATARS.map((a) => [a.id, { label: a.label, src: a.src }] as const),
]);

export function isBuiltinAvatar(id: string): boolean {
  return BY_ID.has(id);
}

export function builtinAvatar(id: string): BuiltinAvatar | undefined {
  return BUILTIN_AVATARS.find((a) => a.id === id);
}

export type ResolvedAvatar =
  | { kind: "image"; src: string; label: string }
  | { kind: "emoji"; emoji: string; label: string };

/** What to draw for a stored avatar value (built-in id, uploaded photo or a legacy emoji). */
export function resolveAvatar(avatar: string | undefined, name = "Profile"): ResolvedAvatar {
  if (avatar?.startsWith("builtin:")) {
    const found = BY_ID.get(avatar.slice(8));
    if (found) return { kind: "image", src: found.src, label: found.label };
  }
  if (avatar?.startsWith("upload:")) {
    return { kind: "image", src: `/api/user/avatar/${encodeURIComponent(avatar.slice(7))}`, label: `${name}'s photo` };
  }
  return { kind: "emoji", emoji: avatar && !avatar.includes(":") ? avatar : "👤", label: name };
}
